package ecmaregex

import (
	"fmt"
	"os"
	"runtime"
	"slices"
	"strconv"
	"testing"
	"unicode"

	"github.com/MichaelKinsy/PiG/internal/jsstring"
)

// The golden files are generated by gen/golden.mjs with Node 24 (V8 13.6, Unicode 17), the engine Pi runs on: node gen/golden.mjs, run from this directory. For every pattern of gen/patterns.txt the generator records whether new RegExp(source, "u") and new RegExp(source) compile and, for each input of the shared pool, what RegExp.prototype.test returns. golden_property.json holds the code point ranges V8 matches for every \p{...} expression it accepts, and the expressions it rejects. Pi commit 6d4b7443 (packages/schema/src/shared.ts sharedRegex) is the caller these results stand for.

type goldenRegex struct {
	Node   string   `json:"node"`
	V8     string   `json:"v8"`
	Inputs []string `json:"inputs"`
	Rows   []struct {
		Pattern string  `json:"p"`
		Unicode *string `json:"u"`
		AnnexB  *string `json:"a"`
		// UnicodeError and AnnexBError are the messages of the SyntaxErrors of a pattern that does not compile.
		UnicodeError string `json:"ue"`
		AnnexBError  string `json:"ae"`
	} `json:"rows"`
}

type goldenProperty struct {
	Node     string         `json:"node"`
	Unicode  string         `json:"unicode"`
	Sets     [][]rune       `json:"sets"`
	Exprs    map[string]int `json:"exprs"`
	Rejected []string       `json:"rejected"`
}

// unpackBit reads bit i of a string that packs booleans four to a hex digit, the first in the high bit.
func unpackBit(packed string, i int) bool {
	digit, _ := strconv.ParseUint(packed[i/4:i/4+1], 16, 8)
	return digit>>(3-i%4)&1 == 1
}

func readGolden[T any](t *testing.T, name string, into *T) {
	t.Helper()
	data, err := os.ReadFile("testdata/" + name)
	if err != nil {
		t.Fatal(err)
	}
	// The golden strings may hold the escape of a lone surrogate, which a Go string keeps as WTF-8.
	if err := jsstring.UnmarshalKeepingSurrogates(data, into); err != nil {
		t.Fatalf("%s: %v", name, err)
	}
}

func TestGoldenRegex(t *testing.T) {
	var golden goldenRegex
	readGolden(t, "golden_regex.json", &golden)
	if len(golden.Rows) < 400 {
		t.Fatalf("golden has only %d rows", len(golden.Rows))
	}
	for _, row := range golden.Rows {
		t.Run(row.Pattern, func(t *testing.T) {
			compare := func(mode string, compile func(string) (*Regexp, error), want *string, message string) {
				re, err := compile(row.Pattern)
				if want == nil {
					if err == nil {
						t.Errorf("%s: compiled, V8 rejects %+q", mode, row.Pattern)
					} else if err.Error() != message {
						t.Errorf("%s: error %q, V8 says %q", mode, err.Error(), message)
					}
					return
				}
				if err != nil {
					t.Errorf("%s: %q: %v, V8 accepts it", mode, row.Pattern, err)
					return
				}
				for i, input := range golden.Inputs {
					if isKnownGap(mode, row.Pattern, input) {
						continue
					}
					if got, wantMatch := re.MatchString(input), unpackBit(*want, i); got != wantMatch {
						t.Errorf("%s: %+q.test(%+q) = %v, V8 says %v", mode, row.Pattern, input, got, wantMatch)
					}
				}
			}
			compare("u", Compile, row.Unicode, row.UnicodeError)
			compare("annexB", CompileAnnexB, row.AnnexB, row.AnnexBError)
			if got, want := Valid(row.Pattern), row.Unicode != nil; got != want {
				t.Errorf("Valid(%q) = %v, want %v", row.Pattern, got, want)
			}
		})
	}
}

// withoutSurrogates returns the sorted, merged ranges of the flat [lo, hi, ...] list with U+D800..U+DFFF removed: Go strings hold no surrogates, so the generator does not probe them either.
func withoutSurrogates(flat []rune) []rune {
	var out []rune
	add := func(lo, hi rune) {
		if lo > hi {
			return
		}
		if n := len(out); n > 0 && out[n-1]+1 >= lo {
			out[n-1] = max(out[n-1], hi)
			return
		}
		out = append(out, lo, hi)
	}
	for i := 0; i < len(flat); i += 2 {
		lo, hi := flat[i], flat[i+1]
		add(lo, min(hi, 0xD7FF))
		add(max(lo, 0xE000), hi)
	}
	return out
}

func flatten(set runeSet) []rune {
	var flat []rune
	for _, r := range set {
		flat = append(flat, r.lo, r.hi)
	}
	return flat
}

func TestGoldenPropertyRanges(t *testing.T) {
	var golden goldenProperty
	readGolden(t, "golden_property.json", &golden)
	// The sets come from Go's tables, so a toolchain on another Unicode version than V8's fails the comparison; every message names both versions.
	versions := fmt.Sprintf("Go %s has Unicode %s, the golden's V8 has Unicode %s", runtime.Version(), unicode.Version, golden.Unicode)
	t.Log(versions)
	if len(golden.Exprs) < 1500 {
		t.Fatalf("golden has only %d expressions", len(golden.Exprs))
	}
	for expr, id := range golden.Exprs {
		set, ok := propertyRanges(expr)
		if !ok {
			t.Errorf("\\p{%s}: rejected, V8 accepts it (%s)", expr, versions)
			continue
		}
		if got, want := withoutSurrogates(flatten(set)), withoutSurrogates(golden.Sets[id]); !slices.Equal(got, want) {
			t.Errorf("\\p{%s}: %s (%s)", expr, describeRangeDifference(got, want), versions)
		}
	}
	for _, expr := range golden.Rejected {
		if _, ok := propertyRanges(expr); ok {
			t.Errorf("\\p{%s}: accepted, V8 rejects it (%s)", expr, versions)
		}
		for _, source := range []string{`\p{` + expr + `}`, `\P{` + expr + `}`} {
			if Valid(source) {
				t.Errorf("Valid(%q) = true, V8 rejects it", source)
			}
		}
	}
}

// describeRangeDifference names the first code point where two range lists disagree.
func describeRangeDifference(got, want []rune) string {
	in := func(flat []rune, r rune) bool {
		for i := 0; i < len(flat); i += 2 {
			if r >= flat[i] && r <= flat[i+1] {
				return true
			}
		}
		return false
	}
	for r := rune(0); r <= unicode.MaxRune; r++ {
		if in(got, r) != in(want, r) {
			return fmt.Sprintf("first difference at U+%04X: ours %v, V8 %v", r, in(got, r), in(want, r))
		}
	}
	return "ranges differ"
}

type goldenCase struct {
	Node        string   `json:"node"`
	UnicodeFlag [][]rune `json:"unicodeFlag"`
	Plain       [][]rune `json:"plain"`
}

// TestGoldenCaseClasses compares the sets of characters that the i flag treats as equal with the ones V8 reports.
func TestGoldenCaseClasses(t *testing.T) {
	var golden goldenCase
	readGolden(t, "golden_case.json", &golden)
	versions := fmt.Sprintf("Go %s has Unicode %s", runtime.Version(), unicode.Version)
	for _, mode := range []struct {
		name    string
		unicode bool
		want    [][]rune
	}{{"u", true, golden.UnicodeFlag}, {"plain", false, golden.Plain}} {
		got := slices.Clone(caseTable(mode.unicode).classes)
		want := slices.Clone(mode.want)
		byFirst := func(a, b []rune) int { return int(a[0]) - int(b[0]) }
		slices.SortFunc(got, byFirst)
		slices.SortFunc(want, byFirst)
		if len(want) < 1000 {
			t.Fatalf("%s: golden has only %d classes", mode.name, len(want))
		}
		wanted := map[rune][]rune{}
		for _, class := range want {
			wanted[class[0]] = class
		}
		for _, class := range got {
			if !slices.Equal(wanted[class[0]], class) {
				t.Errorf("%s: class %x, V8 has %x (%s)", mode.name, class, wanted[class[0]], versions)
			}
			delete(wanted, class[0])
		}
		for first, class := range wanted {
			t.Errorf("%s: no class starts at %x, V8 has %x (%s)", mode.name, first, class, versions)
		}
	}
}

// A gapCase is a result where this package differs from V8: V8 answers v8 and this package the opposite.
type gapCase struct {
	mode, pattern, input string
	v8                   bool
}

// knownGaps are the results that differ from V8. Most are backreferences inside a case-insensitive modifier group. V8 compares the two texts with Canonicalize: simple case folding with the u flag, the upper case of each code unit without it. regexp2 compares them with unicode.ToLower, so it misses pairs that fold together without sharing a lower case (ς and σ in both modes, ſ and s with the u flag) and equates pairs that share a lower case without folding together (İ and i in both modes, the Kelvin sign and k without the u flag). The golden replay skips these results and TestKnownGaps pins the answers this package gives, so a change in either is noticed.
var knownGaps = []gapCase{
	{"u", `^(?i:(\w)\1)$`, "sſ", true},
	{"u", `^(?i:(\w)\1)$`, "iİ", false},
	{"annexB", `^(?i:(\w)\1)$`, "iİ", false},
	{"annexB", `^(?i:(\w)\1)$`, "k\u212a", false},
	{"u", `^(?i:(s)\1)$`, "sſ", true},
	{"u", `^(?i:(\u017f)\1)$`, "sſ", true},
	{"u", `^(?i:(σ)\1)$`, "σς", true},
	{"u", `^(?i:(σ)\1)$`, "ςσ", true},
	{"annexB", `^(?i:(σ)\1)$`, "σς", true},
	{"annexB", `^(?i:(σ)\1)$`, "ςσ", true},
	{"u", `^(?i:(ς)\1)$`, "σς", true},
	{"u", `^(?i:(ς)\1)$`, "ςσ", true},
	{"annexB", `^(?i:(ς)\1)$`, "σς", true},
	{"annexB", `^(?i:(ς)\1)$`, "ςσ", true},
	{"u", `^(?i:(i)\1)$`, "iİ", false},
	{"annexB", `^(?i:(i)\1)$`, "iİ", false},
	{"u", `^(?i:(İ)\1)$`, "İi", false},
	{"annexB", `^(?i:(İ)\1)$`, "İi", false},
	{"annexB", `^(?i:(k)\1)$`, "k\u212a", false},
	{"annexB", `^(?i:(\u212a)\1)$`, "\u212ak", false},
	{"u", `^(?i:(.)\1)$`, "sſ", true},
	{"u", `^(?i:(.)\1)$`, "σς", true},
	{"u", `^(?i:(.)\1)$`, "ςσ", true},
	{"u", `^(?i:(.)\1)$`, "iİ", false},
	{"u", `^(?i:(.)\1)$`, "İi", false},
	{"annexB", `^(?i:(.)\1)$`, "σς", true},
	{"annexB", `^(?i:(.)\1)$`, "ςσ", true},
	{"annexB", `^(?i:(.)\1)$`, "iİ", false},
	{"annexB", `^(?i:(.)\1)$`, "İi", false},
	{"annexB", `^(?i:(.)\1)$`, "k\u212a", false},
	{"annexB", `^(?i:(.)\1)$`, "\u212ak", false},
	// The rows below are not about case folding. V8 answers differently for reasons its source does not make plain: \W or a class after a case-insensitive modifier group in plain mode, and a long alternation under the m and s modifiers.
	{"annexB", `(?i:[\n\p{Lu}\x62]|[^a-c😀x-z])\W\u0061`, "A\u03c3a\u00b5", true},
	{"annexB", `(?im-s:(?<n1>(?:)()\s{|\u212a[\n\0K]()?)(?:()))`, "\u212ak", false},
	{"annexB", `(?ims:(?m:(?=\aΩ\c){,2}\n)(?<n1>\b(?=xx??)\d)|\/(\w)[aA]|[\u0061a-c\cA])+[^\ude00]`, "AB", false},
}

func isKnownGap(mode, pattern, input string) bool {
	return slices.ContainsFunc(knownGaps, func(g gapCase) bool { return g.mode == mode && g.pattern == pattern && g.input == input })
}

func TestKnownGaps(t *testing.T) {
	var golden goldenRegex
	readGolden(t, "golden_regex.json", &golden)
	for _, gap := range knownGaps {
		compile := Compile
		if gap.mode == "annexB" {
			compile = CompileAnnexB
		}
		re, err := compile(gap.pattern)
		if err != nil {
			t.Errorf("%s %q: %v", gap.mode, gap.pattern, err)
			continue
		}
		if got := re.MatchString(gap.input); got == gap.v8 {
			t.Errorf("%s %q.test(%q) = %v, V8's answer: the gap is closed, remove it from knownGaps", gap.mode, gap.pattern, gap.input, got)
		}
		// The table must state what V8 says, as the golden recorded it.
		recorded := false
		for _, row := range golden.Rows {
			bits := row.Unicode
			if gap.mode == "annexB" {
				bits = row.AnnexB
			}
			if row.Pattern != gap.pattern || bits == nil {
				continue
			}
			i := slices.Index(golden.Inputs, gap.input)
			recorded = i >= 0
			if recorded && unpackBit(*bits, i) != gap.v8 {
				t.Errorf("%s %q.test(%q): V8 says %v in the golden, the table says %v", gap.mode, gap.pattern, gap.input, !gap.v8, gap.v8)
			}
		}
		if !recorded {
			t.Errorf("%s %q.test(%q) is not in the golden", gap.mode, gap.pattern, gap.input)
		}
	}
}
